    void incrementalReuse(){QString source;for(int i=0;i<5000;++i)source+=QString("Paragraph %1: **bold** and text.\n\n").arg(i);Markdown::parse(source,"extended");QString changed=source;int at=changed.indexOf("Paragraph 2500");changed.insert(at+10,"inserted ");auto partial=Markdown::parse(changed,"extended");int units=Markdown::lastParsedUnits,reused=Markdown::reusedNodes;QVERIFY(units<2000);QVERIFY(reused>4900);auto full=Markdown::parse(changed,"extended",true);QCOMPARE(partial->root.children.size(),full->root.children.size());for(int i=0;i<full->root.children.size();++i){QCOMPARE(partial->root.children[i].start,full->root.children[i].start);QCOMPARE(partial->root.children[i].end,full->root.children[i].end);QCOMPARE(partial->root.children[i].type,full->root.children[i].type);}}
