    void nativeFieldWritesAndSaves(){QSettings().setValue("dialect","extended");QTemporaryDir dir;Window window;QString source="| A | B |\n| --- | --- |\n| old | value |\n";window.editor->setPlainText(source);window.setMode("live");window.show();window.editor->liveController->refresh();auto widget=window.editor->viewport()->findChild<TableWidget *>();QVERIFY(widget);widget->table->setCurrentCell(1,0);widget->table->editItem(widget->table->item(1,0));QTest::qWait(30);auto field=widget->table->findChild<Editor *>();QVERIFY(field);field->selectAll();field->insertPlainText("first");field->insertPlainText(" second");QVERIFY(window.editor->toPlainText().contains("first second"));QVERIFY(window.savePath(dir.filePath("active.md")));QFile file(dir.filePath("active.md"));QVERIFY(file.open(QIODevice::ReadOnly));QVERIFY(file.readAll().contains("first second"));window.editor->setFocus();window.editor->undo();QCOMPARE(window.editor->toPlainText(),source);window.editor->document()->setModified(false);}
