    void pdfBookmarks(){QTemporaryDir dir;QTextDocument doc;Markdown::render(&doc,"# Title\n\nText\n\n## 中文标题\n",{},500,"extended");QPrinter printer;printer.setOutputFormat(QPrinter::PdfFormat);auto path=dir.filePath("bookmarks.pdf");printer.setOutputFileName(path);doc.print(&printer);QVERIFY(Services::pdfBookmarks(path,{{"Title",0},{QString::fromUtf8("中文标题"),0}}));QFile file(path);QVERIFY(file.open(QIODevice::ReadOnly));auto bytes=file.readAll();QVERIFY(bytes.contains("/Outlines"));QVERIFY(bytes.contains("/PageMode /UseOutlines"));QFile::remove("parity-export.pdf");QVERIFY(file.copy("parity-export.pdf"));}
    void pandocFormats(){auto executable=Services::pandocExecutable();QVERIFY2(!executable.isEmpty(),"Pandoc must be provisioned for complete export tests");QTemporaryDir dir;auto input=dir.filePath("source.md");QFile source(input);QVERIFY(source.open(QIODevice::WriteOnly));source.write("# Test\n\n**bold** and Chinese.\n\n|A|B|\n|-|-|\n|1|2|\n");source.close();for(auto format:{"docx","epub","odt","rst","mediawiki","latex"}){auto output=dir.filePath(QString("test.")+format);QProcess process;process.start(executable,{input,"--from=markdown","--standalone",QString("--to=")+format,"--output="+output});QVERIFY(process.waitForFinished(20000));QCOMPARE(process.exitCode(),0);QVERIFY(QFileInfo(output).size()>0);if(QStringList{"docx","epub","odt"}.contains(format)){QProcess back;back.start(executable,{output,"--to=gfm"});QVERIFY(back.waitForFinished(20000));QCOMPARE(back.exitCode(),0);QVERIFY(back.readAllStandardOutput().contains("Test"));}}}
    void uploadLoopback(){QTcpServer server;QVERIFY(server.listen(QHostAddress::LocalHost));QByteArray captured;connect(&server,&QTcpServer::newConnection,&server,[&]{auto socket=server.nextPendingConnection();auto bytes=QSharedPointer<QByteArray>::create();connect(socket,&QTcpSocket::readyRead,socket,[&,socket,bytes]{bytes->append(socket->readAll());int end=bytes->indexOf("\r\n\r\n");if(end<0)return;auto length=QRegularExpression("content-length: (\\d+)",QRegularExpression::CaseInsensitiveOption).match(QString::fromLatin1(bytes->left(end)));if(!length.hasMatch()||bytes->size()<end+4+length.captured(1).toInt())return;captured=*bytes;QByteArray body="{\"data\":{\"url\":\"https://images.example.test/test.png\"}}";socket->write("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+QByteArray::number(body.size())+"\r\nConnection: close\r\n\r\n"+body);socket->disconnectFromHost();});});
        QTemporaryDir dir;QImage image(10,10,QImage::Format_RGB32);image.fill(Qt::red);auto path=dir.filePath("test.png");QVERIFY(image.save(path));QSettings settings;settings.setValue("uploadEndpoint",QString("http://127.0.0.1:%1/upload").arg(server.serverPort()));settings.setValue("uploadResultPath","data.url");Window window;window.setMode("source");window.services->tokenProvider=[]{return "dummy-test-token";};QTimer::singleShot(0,[&]{auto dialog=qobject_cast<QFileDialog *>(QApplication::activeModalWidget());QVERIFY(dialog);dialog->selectFile(path);QMetaObject::invokeMethod(dialog,"accept",Qt::QueuedConnection);});window.services->uploadImage();QTRY_VERIFY_WITH_TIMEOUT(window.editor->toPlainText().contains("images.example.test"),5000);QVERIFY(captured.contains("Authorization: Bearer dummy-test-token"));QVERIFY(captured.contains("name=\"file\""));QVERIFY(captured.contains("image/png"));window.editor->document()->setModified(false);settings.remove("uploadEndpoint");}
