    void nestedExtendedAst(){QString source=QString::fromUtf8("前 ==**bold** and *中文*== H~2~O x^**two**^");auto ast=Markdown::parse(source,"extended");auto all=Markdown::descendants(ast->root);int strong=0;for(auto node:all){if(node.type=="strong"){++strong;QVERIFY(source.mid(node.start,node.end-node.start).startsWith("**"));}if(node.type=="mark_inline"){QVERIFY(!node.children.isEmpty());QCOMPARE(node.literal,QString::fromUtf8("**bold** and *中文*"));}}QCOMPARE(strong,2);QTextDocument doc;Markdown::render(&doc,source,{},600,"extended");QVERIFY(!doc.toPlainText().contains("**"));QVERIFY(!doc.toPlainText().contains("=="));QVERIFY(doc.toHtml().contains("font-weight:700"));}
